const item = $input.first().json || {};
const execution = item.execution || {};
const workflow = item.workflow || {};

function redact(val) {
  if (val === null || val === undefined) return '';
  return String(val)
    .replace(/Bearer\s+[A-Za-z0-9._~+/-]+=*/gi, 'Bearer [REDACTED]')
    .replace(/\b(nvapi|sk|ghp|gho|xoxb|xoxp|AIza)[A-Za-z0-9_-]{8,}\b/g, '[REDACTED_KEY]')
    .replace(/((?:x-usami-token|authorization|api[-_]?key|secret|password|token)\s*[:=]\s*)(["']?)[^\s,"';&}]+\2/gi, '$1[REDACTED]')
    .slice(0, 500);
}

const workflowId = String(workflow.id || 'desconhecido');
const workflowName = String(workflow.name || 'Workflow sem nome');
const executionId = String(execution.id || ('err-' + Date.now()));
const mode = String(execution.mode || 'unknown');
const lastNode = execution.lastNodeExecuted ? String(execution.lastNodeExecuted) : null;
const rawErrorMsg = execution.error?.message || execution.error?.description || 'Falha desconhecida no n8n';
const errorMessage = redact(rawErrorMsg);
const timestamp = new Date().toISOString();

let envChannel = '';
try {
  envChannel = ($env && $env.DISCORD_OBS_ERRORS_CHANNEL_ID) ? String($env.DISCORD_OBS_ERRORS_CHANNEL_ID).trim() : '';
} catch {
  envChannel = '';
}
const hasErrorsChannel = Boolean(envChannel && !envChannel.startsWith('CONFIGURE_'));

const record = {
  timestamp,
  executionId,
  workflowId,
  workflowName,
  mode,
  lastNode,
  errorMessage,
  executionUrl: execution.url || null
};

const discordPayload = {
  embeds: [{
    title: `⚠️ Falha em Workflow n8n: ${workflowName}`,
    description: errorMessage,
    color: 15548997,
    fields: [
      { name: 'Workflow ID', value: workflowId, inline: true },
      { name: 'Execução ID', value: executionId, inline: true },
      { name: 'Último Nó', value: lastNode || 'N/D', inline: true },
      { name: 'Modo', value: mode, inline: true }
    ],
    timestamp
  }]
};

return [{
  json: {
    record,
    payloadB64: Buffer.from(JSON.stringify(record), 'utf8').toString('base64'),
    obsErrorsChannelId: envChannel,
    hasErrorsChannel,
    discordPayload
  }
}];

const first = $input.first().json || {};
if (first.error) {
  return [{ json: { hasRows: false, rowsB64: 'W10=', apiError: String(first.error.message || first.error).slice(0, 300) } }];
}

const list = Array.isArray(first.data) ? first.data : (Array.isArray(first) ? first : []);
const rows = [];

for (const exec of list) {
  if (!exec || !exec.id) continue;
  const started = exec.startedAt ? new Date(exec.startedAt).getTime() : NaN;
  const stopped = exec.stoppedAt ? new Date(exec.stoppedAt).getTime() : NaN;
  const durationMs = (Number.isFinite(started) && Number.isFinite(stopped) && stopped >= started)
    ? Math.round(stopped - started)
    : null;
  rows.push({
    execution_id: String(exec.id),
    created_at: exec.startedAt || new Date().toISOString(),
    workflow_id: exec.workflowId ? String(exec.workflowId) : null,
    workflow_name: exec.workflowName ? String(exec.workflowName) : null,
    status: String(exec.status || (exec.finished ? 'success' : 'running')),
    mode: exec.mode ? String(exec.mode) : null,
    duration_ms: durationMs,
    error_message: null
  });
}

return [{
  json: {
    hasRows: rows.length > 0,
    count: rows.length,
    rowsB64: Buffer.from(JSON.stringify(rows), 'utf8').toString('base64')
  }
}];
